def leakage_scan(features: list, target: str) -> list:
    """List features that correlate too well."""
    suspects = []
    for col in features:
        r = portfolio[col].corr(portfolio[target])
        print(f"  {col:<22} corr={r:+.4f}")
        if abs(r) > 0.9:
            suspects.append(col)
